            "For minimally verbal children, add familiar object naming, word combinations and emerging grammatical forms. Short phrases permit examination of syntax, vocabulary variety, intelligibility and multistep commands. Conversational language permits more complex commands, humor and narratives.",
            "Keep earlier skills in view as demands increase. Familiar caregiver interaction can provide a more representative sample than interaction with an unfamiliar examiner. Consider temperament, attention and familiarity with the materials."
